/* ---------------- Tarot-style flip card ---------------- */
function TierCard({ tier, accent = "gold", onBook }) {
  const [flipped, setFlipped] = useState(false);
  const accentColor = accent === "wine" ? "var(--wine)" : "var(--gold)";

  return (
    <div
      className="tier-card"
      onMouseEnter={() => setFlipped(true)}
      onMouseLeave={() => setFlipped(false)}
      onClick={() => setFlipped((f) => !f)}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") setFlipped((f) => !f);
      }}
      style={{ "--accent": accentColor }}
    >
      <div className={`tier-card-inner ${flipped ? "is-flipped" : ""}`}>
        <div className="tier-card-face tier-card-front">
          <Star size={18} style={{ color: accentColor, opacity: 0.85 }} />
          <div className="tier-card-price">₹{tier.price}</div>
          <div className="tier-card-label">{tier.label}</div>
          <div className="tier-card-hint">hover / tap to reveal</div>
        </div>
        <div className="tier-card-face tier-card-back">
          <div className="tier-card-back-label">{tier.label}</div>
          <p className="tier-card-desc">{tier.desc}</p>
          <button
            className="btn-gold btn-small"
            onClick={(e) => {
              e.stopPropagation();
              onBook(tier);
            }}
          >
            Book — ₹{tier.price}
          </button>
        </div>
      </div>
    </div>
  );
}

/* ---------------- UPI payment helpers ----------------
   No gateway, no backend — this builds a standard UPI deep link
   ("upi://pay?...") that any UPI app (GPay/PhonePe/Paytm/BHIM) understands,
   plus a QR code image of that same link for desktop users.
   Payments land straight in the UPI_ID below; there is no automatic
   confirmation, so the flow ends with a WhatsApp nudge so the booking
   can be confirmed by hand. ------------------------------------------- */
const UPI_ID = "yourfriend@upi"; // TODO: replace with the real UPI ID (VPA)
const UPI_PAYEE_NAME = "Veiled Hour"; // shown inside the customer's UPI app
const WHATSAPP_NUMBER = "91XXXXXXXXXX"; // TODO: country code + number, no + or spaces

function buildUpiLink({ amount, note }) {
  const params = new URLSearchParams({
    pa: UPI_ID,
    pn: UPI_PAYEE_NAME,
    am: String(amount),
    cu: "INR",
    tn: note,
  });
  return `upi://pay?${params.toString()}`;
}

function buildUpiQrSrc(upiLink) {
  return `https://api.qrserver.com/v1/create-qr-code/?size=220x220&margin=8&data=${encodeURIComponent(upiLink)}`;
}

