/* ---------------- Custom calendar date-picker ---------------- */
const MONTH_NAMES = ["January","February","March","April","May","June","July","August","September","October","November","December"];
const WEEKDAY_LABELS = ["S","M","T","W","T","F","S"];

function TarotCalendar({ value, onChange }) {
  const [open, setOpen] = useState(false);
  const today = new Date();
  const initial = value ? new Date(value + "T00:00:00") : today;
  const [viewYear, setViewYear] = useState(initial.getFullYear());
  const [viewMonth, setViewMonth] = useState(initial.getMonth());
  const wrapRef = useRef(null);

  useEffect(() => {
    const onClick = (e) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target)) setOpen(false);
    };
    document.addEventListener("mousedown", onClick);
    return () => document.removeEventListener("mousedown", onClick);
  }, []);

  const daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();
  const firstWeekday = new Date(viewYear, viewMonth, 1).getDay();
  const cells = [];
  for (let i = 0; i < firstWeekday; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(d);

  const pad = (n) => String(n).padStart(2, "0");
  const fmt = (d) => `${viewYear}-${pad(viewMonth + 1)}-${pad(d)}`;

  const changeMonth = (delta) => {
    let m = viewMonth + delta;
    let y = viewYear;
    if (m < 0) { m = 11; y -= 1; }
    if (m > 11) { m = 0; y += 1; }
    setViewMonth(m);
    setViewYear(y);
  };

  const displayValue = value
    ? `${MONTH_NAMES[Number(value.split("-")[1]) - 1]} ${Number(value.split("-")[2])}, ${value.split("-")[0]}`
    : "";

  return (
    <div className="tarot-calendar" ref={wrapRef}>
      <button
        type="button"
        className="field-input calendar-trigger"
        onClick={() => setOpen((o) => !o)}
      >
        {displayValue || "Choose a date"}
        <Star size={12} style={{ marginLeft: "auto", color: "var(--gold)" }} />
      </button>

      {open && (
        <div
          className="calendar-dropdown"
          style={{ backgroundImage: `url(${IMG_CALENDAR_BG})` }}
        >
          <div className="calendar-overlay" />
          <div className="calendar-content">
            <div className="calendar-header">
              <button type="button" onClick={() => changeMonth(-1)}>‹</button>
              <span>{MONTH_NAMES[viewMonth]} {viewYear}</span>
              <button type="button" onClick={() => changeMonth(1)}>›</button>
            </div>
            <div className="calendar-weekdays">
              {WEEKDAY_LABELS.map((w, i) => <span key={i}>{w}</span>)}
            </div>
            <div className="calendar-grid">
              {cells.map((d, i) =>
                d ? (
                  <button
                    type="button"
                    key={i}
                    className={`calendar-day ${value === fmt(d) ? "is-selected" : ""}`}
                    onClick={() => {
                      onChange(fmt(d));
                      setOpen(false);
                    }}
                  >
                    {d}
                  </button>
                ) : (
                  <span key={i} className="calendar-day-empty" />
                )
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function BookingPage({ selectedTier, setSelectedTier }) {
  const allTiers = [
    ...QUESTION_TIERS.map((t) => ({ category: "Quick Questions", ...t })),
    ...SPREAD_TIERS.map((t) => ({ category: "Spread", ...t })),
    ...LIVE_TIERS.map((t) => ({ category: "Live Open Session", ...t })),
  ];

  const [form, setForm] = useState({ name: "", email: "", date: "", time: "", note: "" });
  const [showError, setShowError] = useState(false);
  const [paymentOpen, setPaymentOpen] = useState(false);
  const [utr, setUtr] = useState("");
  const [confirmed, setConfirmed] = useState(false);
  const [copied, setCopied] = useState(false);

  const update = (field) => (e) => setForm((f) => ({ ...f, [field]: e.target.value }));

  const fieldsComplete = Boolean(selectedTier && form.name && form.email && form.date && form.time);

  const revealPayment = useCallback(() => {
    if (!fieldsComplete) {
      setShowError(true);
      return;
    }
    setShowError(false);
    setPaymentOpen(true);
  }, [fieldsComplete]);

  const upiNote = selectedTier ? `${selectedTier.label} - ${form.name || "Booking"}`.slice(0, 50) : "";
  const upiLink = selectedTier ? buildUpiLink({ amount: selectedTier.price, note: upiNote }) : "";
  const qrSrc = upiLink ? buildUpiQrSrc(upiLink) : "";

  const whatsappText = selectedTier
    ? `Hi! I've paid ₹${selectedTier.price} for ${selectedTier.category} — ${selectedTier.label}.%0AName: ${form.name}%0AEmail: ${form.email}%0ADate: ${form.date} ${form.time}%0AUTR/Ref: ${utr || "(sending screenshot)"}`
    : "";
  const whatsappLink = `https://wa.me/${WHATSAPP_NUMBER}?text=${whatsappText}`;

  const copyUpiId = useCallback(() => {
    navigator.clipboard?.writeText(UPI_ID);
    setCopied(true);
    setTimeout(() => setCopied(false), 1800);
  }, []);

  return (
    <div
      className="booking-page-bg"
      style={{ backgroundImage: `url(${IMG_MOON_PHASE_CIRCLE})` }}
    >
      <div className="booking-page-overlay" />
      <div className="section booking-page-content">
      <Reveal>
        <div className="eyebrow"><Video size={14} /> Book a session</div>
        <h1 className="page-title">Reserve your time</h1>
      </Reveal>

      <div className="booking-grid">
        <Reveal delay={80}>
          <div className="panel">
            <label className="field-label">Session</label>
            <select
              className="field-input"
              value={selectedTier?.id || ""}
              onChange={(e) => {
                const t = allTiers.find((x) => x.id === e.target.value);
                setSelectedTier(t || null);
              }}
            >
              <option value="" disabled>Choose a session…</option>
              {allTiers.map((t) => (
                <option key={t.id} value={t.id}>
                  {t.category} — {t.label} (₹{t.price})
                </option>
              ))}
            </select>

            <label className="field-label">Your name</label>
            <input className="field-input" value={form.name} onChange={update("name")} placeholder="Full name" />

            <label className="field-label">Email</label>
            <input className="field-input" type="email" value={form.email} onChange={update("email")} placeholder="you@example.com" />

            <div className="field-row">
              <div style={{ flex: 1 }}>
                <label className="field-label">Date</label>
                <TarotCalendar value={form.date} onChange={(d) => setForm((f) => ({ ...f, date: d }))} />
              </div>
              <div style={{ flex: 1 }}>
                <label className="field-label"><Clock size={12} style={{ marginRight: 4 }} />Time</label>
                <input className="field-input" type="time" value={form.time} onChange={update("time")} />
              </div>
            </div>

            <label className="field-label">Anything you want the reader to know (optional)</label>
            <textarea className="field-input" rows={3} value={form.note} onChange={update("note")} placeholder="Context for your questions or spread…" />

            {showError && (
              <p className="form-error">Please fill in every field and select a session first.</p>
            )}

            {!confirmed && (
              <button className="btn-gold" style={{ width: "100%", marginTop: 16 }} onClick={revealPayment}>
                {selectedTier ? `Continue to pay ₹${selectedTier.price}` : "Select a session first"}
              </button>
            )}

            {paymentOpen && !confirmed && (
              <div className="upi-panel">
                <p className="upi-panel-title">Scan or tap to pay via UPI</p>
                <img src={qrSrc} alt="UPI payment QR code" className="upi-qr" />

                <a className="btn-gold upi-app-link" href={upiLink}>
                  Open in UPI app
                </a>

                <div className="upi-id-row">
                  <span>{UPI_ID}</span>
                  <button type="button" className="upi-copy-btn" onClick={copyUpiId}>
                    {copied ? "Copied" : "Copy ID"}
                  </button>
                </div>

                <p className="upi-hint">
                  Pay ₹{selectedTier?.price} to the ID above, then let us know so the booking can be
                  confirmed — payments aren't verified automatically.
                </p>

                <label className="field-label">Transaction ref / UTR (optional, speeds up confirmation)</label>
                <input
                  className="field-input"
                  value={utr}
                  onChange={(e) => setUtr(e.target.value)}
                  placeholder="12-digit UPI ref number"
                />

                <a
                  className="btn-ghost"
                  style={{ width: "100%", marginTop: 10, textAlign: "center", justifyContent: "center" }}
                  href={whatsappLink}
                  target="_blank"
                  rel="noreferrer"
                  onClick={() => setConfirmed(true)}
                >
                  I've paid — notify on WhatsApp
                </a>
              </div>
            )}

            {confirmed && (
              <div className="paid-banner">
                <Check size={16} /> Thanks — we've sent your payment details over WhatsApp. Your booking
                will be confirmed and a Meet link emailed to you once payment is verified.
              </div>
            )}
          </div>
        </Reveal>

        <Reveal delay={160}>
          <div className="panel summary-panel">
            <img src={IMG_HAND_CARDS_ACCENT} alt="" className="summary-accent" />
            <h3>Summary</h3>
            {selectedTier ? (
              <>
                <p className="summary-category">{selectedTier.category}</p>
                <p className="summary-label">{selectedTier.label}</p>
                <p className="summary-desc">{selectedTier.desc}</p>
                <div className="summary-price">₹{selectedTier.price}</div>
              </>
            ) : (
              <p className="summary-desc">Pick a session from the pricing page, or choose one from the dropdown here.</p>
            )}
            <div className="summary-note">
              <Mail size={14} /> Recording delivered by email or Google Drive link after your session.
            </div>
          </div>
        </Reveal>
      </div>
      </div>
    </div>
  );
}

function AboutPage() {
  return (
    <div>
      <div className="page-banner page-banner-tall" style={{ backgroundImage: `url(${IMG_HAND_FAN_TEXTURE})` }}>
        <div className="page-banner-overlay" />
        <Reveal className="page-banner-content">
          <div className="eyebrow"><Moon size={14} /> About</div>
          <h1 className="page-title" style={{ color: "var(--moon)" }}>A calm, honest read</h1>
          <p className="page-sub" style={{ maxWidth: 520 }}>
            Every session is live, one-on-one, and recorded so you can sit
            with it again later. No vague generalities — each reading stays
            close to the question you actually asked.
          </p>
        </Reveal>
      </div>

      <div className="section">
        <div className="about-grid">
          <Reveal>
            <img src={IMG_EMPRESS_LILY} alt="The Empress tarot card resting against a red lily" className="about-image" />
          </Reveal>
          <Reveal delay={100}>
            <div className="parchment-note" style={{ backgroundImage: `url(${IMG_PARCHMENT_NOTE})` }}>
              <p>
                "I read the way I'd want to be read for — patiently, and
                without dressing up what the cards actually show. Bring the
                real question. That's the one worth sitting with."
              </p>
            </div>
          </Reveal>
        </div>
      </div>
    </div>
  );
}

/* ============================================================
   APP SHELL
   ============================================================ */

export default function App() {
  const [page, setPage] = useState("home");
  const [menuOpen, setMenuOpen] = useState(false);
  const [selectedTier, setSelectedTier] = useState(null);

  useEffect(() => {
    if (document.getElementById("tarot-font-import")) return;
    const link = document.createElement("link");
    link.id = "tarot-font-import";
    link.rel = "stylesheet";
    link.href = FONT_IMPORT_URL;
    document.head.appendChild(link);
  }, []);

  const navigate = (p) => {
    setPage(p);
    setMenuOpen(false);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const navItems = [
    { id: "home", label: "Home" },
    { id: "pricing", label: "Sessions" },
    { id: "booking", label: "Book" },
    { id: "about", label: "About" },
  ];

  return (
    <div className="app-root">
      <style>{CSS}</style>
      <div className="bg-layer">
        <div
          className="bg-photo-tile"
          style={{ backgroundImage: `url(${IMG_CANDLES_SPREAD})` }}
        />
        <div className="bg-photo-overlay" />
        <Starfield />
      </div>

      <header className="nav">
        <div className="nav-brand" onClick={() => navigate("home")}>
          <Sparkles size={18} style={{ color: "var(--gold)" }} />
          <span>Veiled Hour</span>
        </div>
        <nav className="nav-links">
          {navItems.map((item) => (
            <button
              key={item.id}
              className={`nav-link ${page === item.id ? "active" : ""}`}
              onClick={() => navigate(item.id)}
            >
              {item.label}
            </button>
          ))}
        </nav>
        <button className="nav-burger" onClick={() => setMenuOpen((m) => !m)} aria-label="Menu">
          {menuOpen ? <X size={20} /> : <Menu size={20} />}
        </button>
      </header>

      {menuOpen && (
        <div className="nav-mobile">
          {navItems.map((item) => (
            <button key={item.id} className="nav-mobile-link" onClick={() => navigate(item.id)}>
              {item.label}
            </button>
          ))}
        </div>
      )}

      <main className="main-content">
        <div key={page} className="page-transition">
          {page === "home" && <HomePage navigate={navigate} />}
          {page === "pricing" && <PricingPage navigate={navigate} setSelectedTier={setSelectedTier} />}
          {page === "booking" && <BookingPage selectedTier={selectedTier} setSelectedTier={setSelectedTier} />}
          {page === "about" && <AboutPage />}
        </div>
      </main>

      <footer className="footer">
        <p>Veiled Hour — live tarot readings, one session at a time.</p>
      </footer>
    </div>
  );
}

